-- composition of rule kernels L:optimize_projections x P:OutputRequirements (datafusion), template cte_twice
WITH ka AS (SELECT 2 AS c0), kb AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a1.c1 AS c0, 100.0::float8 AS c1 FROM t0 AS a1, generate_series (10, 1) AS a2 (c0) GROUP BY GROUPING SETS ((a1.c1), ())) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (SELECT 2 AS c0) AS ka) + (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a1.c1 AS c0, 100.0::float8 AS c1 FROM t0 AS a1, generate_series (10, 1) AS a2 (c0) GROUP BY GROUPING SETS ((a1.c1), ())) AS kb)
